/**
 * 负责：从原配置与显式选项装配 World、角色组件、机制和真实游戏运行时。
 * 输入：BoardConfig、角色与随机源选项；输出：原初始化对象及同一参数和 RulePlan owner。
 * 先在原 deal fork 后验证支持范围并洗牌，再初始化实体；不读取模型认证或选择玩家动作。
 * 校验后的配置克隆在角色初始化前冻结，原 World、actor、RNG 和调用方均不冻结。
 * PhaseManager 创建规则计划，流水线、开局上下文和记录入口消费同一引用。
 */
import {
  createAliveComponent,
  createBadgeComponent,
  createCampComponent,
  createStatusMarksComponent,
  createVotingRightComponent,
} from "../game/observation/component-presentation";
import { installNobleBodyAuthority } from "../game/mechanisms/roles/noble_secret_body/authority";
import { installAnimalAuthority } from "../game/mechanisms/roles/animal_dream/authority";
import { buildSupportedRoleDeck } from "../rulesets/supported-role-deck";
import { BoardParameters, bindBoardParameters } from "../rulesets/board-parameters";
import type { RulePlan } from "../rulesets/rule-plan";
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { installRadiantEclipseBoard } from "../game/mechanisms/roles/radiant_eclipse/night_frame";
import { installMistRavenBoard } from "../game/mechanisms/roles/mist_raven/night_frame";
import { installScholarMentorBoard } from "../game/mechanisms/roles/scholar_mentor/night_frame";
import { installTimeConsortBoard } from "../game/mechanisms/roles/time_wolf_consort/night_frame";
import { installWolfSorcererBoard } from "../game/mechanisms/roles/wolf_sorcerer/night_frame";
import { installTricksterBoard } from "../game/mechanisms/roles/trickster/night_frame";
import { installOrderPrinceBoard } from "../game/mechanisms/roles/order_prince/authority";
import { installMagicianBoard } from "../game/mechanisms/roles/magician/night_frame";
import { installNightmareBoard } from "../game/mechanisms/roles/nightmare_shadow/night_frame";
import { installEvilKnightBoard } from "../game/mechanisms/roles/evil_knight/night_frame";
import { installDemonHunter } from "../game/mechanisms/roles/demon_hunter/authority";
import { WinConditionRegistry as PureWhiteWinRegistry } from "../game/mechanisms/registries/win_condition_registry";
import { createEliminationWinConditionSpecs } from "../game/mechanisms/win_conditions/default_specs";
import { installGhostBride } from "../game/mechanisms/roles/ghost_bride/authority";
import { installLonelyGirl } from "../game/mechanisms/roles/lonely_girl/lifecycle";
import { installWildChild } from "../game/mechanisms/roles/wild_child/lifecycle";
import { installInitialRoster } from "../core/domain/initial_roster";
import { installShapeshifterDeal } from "../game/mechanisms/roles/shapeshifter/deal";
import { installThiefDeal } from "../game/mechanisms/roles/thief/deal";
import { supportsWallRoles } from "../game/mechanisms/events/wall_notes/authority";
import { text } from "@ai-werewolf-arena/game-text";

import { COMPONENT } from "../core/domain/components/names";
import type { RoleComponent } from "../core/domain/components/role";
import { createRoleComponent } from "../game/observation/role-presentation";

import { createVictoryComponent } from "../core/domain/components/victory";
import { createIdentityComponent } from "../core/domain/entities/player";
import { BoardConfig, EntityId, Role } from "../core/domain/model";
import {
  getDefaultWinConditionRegistry,
  getDefaultRoleCatalog,
  assignInitialSheriff,
  createDefaultRoleRegistry,
} from "../game/mechanisms";
import { ConditionRegistry } from "../core/domain/registries/condition_registry";
import { DamageResolutionSystem } from "../core/domain/systems/damage_resolution_system";
import { World } from "../core/domain/world";
import { PhaseManager } from "../game/engine/phase_manager";
import { ToolGateway } from "../game/gateway/tool_gateway";
import { createRandom, shuffled, type RandomSource } from "../core/domain/random";
import type { Locale } from "@ai-werewolf-arena/game-contract";

/**
 * bootstrap 负责把“配置”装配成“可运行对局上下文”。
 * 这是服务层启动游戏引擎的唯一入口。
 */
export interface BootstrapResult {
  world: World;
  readonly boardConfig: ReadonlyBoardConfig;
  readonly parameters: BoardParameters;
  readonly rulePlan: RulePlan;
  phaseManager: PhaseManager;
  playerIds: EntityId[];
  random: RandomSource;
  dealMode: "random" | "fixed";
}

export interface BootstrapOptions {
  locale?: Locale;
  playerNames?: Readonly<Record<string, string>>;
  random?: RandomSource;
  /** 仅供 controller fixture：明确牌堆仍按原数量严格验证。 */
  fixedRoles?: readonly Role[];
  /** 显式离线因果测试输入，不是板子或模型参数。 */
  faultPlan?: unknown;
}

/**
 * 按板子配置完成一次完整引擎装配，返回可直接运行的上下文对象。
 */
export function bootstrapGame(
  config: BoardConfig,
  options: BootstrapOptions = {},
): BootstrapResult {
  const world = new World(options.locale);
  const random = options.random ?? createRandom();
  // 先完成实体与组件初始化，再创建系统与管理器，避免空引用。
  const initialized = createPlayers(world, config, options, random);
  const playerIds = initialized.playerIds;
  const parameters = initialized.parameters;
  const boardConfig = parameters.board;
  assignInitialSheriff(world, boardConfig, playerIds);

  const roleRegistry = createDefaultRoleRegistry();
  const damageResolutionSystem = new DamageResolutionSystem();
  const conditionRegistry = new ConditionRegistry(
    boardConfig.pureWhite || boardConfig.animalDream
      ? new PureWhiteWinRegistry(
          createEliminationWinConditionSpecs(
            boardConfig.pureWhite?.eliminationPriority ?? "awa_wolf_priority_v1",
          ),
        )
      : getDefaultWinConditionRegistry(),
  );
  const toolGateway = new ToolGateway();

  const phaseManager = new PhaseManager(
    world,
    boardConfig,
    toolGateway,
    roleRegistry,
    conditionRegistry,
    damageResolutionSystem,
    random,
    { faultPlan: options.faultPlan },
  );

  return Object.freeze({
    world,
    boardConfig,
    parameters,
    rulePlan: phaseManager.getRulePlan(),
    phaseManager,
    playerIds,
    random,
    dealMode: options.fixedRoles ? "fixed" : "random",
  });
}

function createPlayers(
  world: World,
  inputConfig: BoardConfig,
  options: BootstrapOptions,
  random: RandomSource,
): { playerIds: EntityId[]; parameters: BoardParameters } {
  const fixedRoles = options.fixedRoles;
  const dealRandom = random.fork("deal");
  const candidateParameters = BoardParameters.compile(inputConfig);
  const config = candidateParameters.board;
  const roles = buildRoleDeck(config, fixedRoles, dealRandom);
  const parameters = bindBoardParameters(world, candidateParameters);
  const ids: EntityId[] = [];
  const roleCatalog = getDefaultRoleCatalog();

  for (let seat = 1; seat <= config.boardSize; seat++) {
    const entityId = world.createEntity();
    const role = roles[seat - 1];
    const roleComp = createRoleComponent(role, roleCatalog.getCamp(role), world.locale);
    roleCatalog.applyRuntime(roleComp, { boardConfig: config, locale: world.locale, world });

    world.addComponent(
      entityId,
      COMPONENT.Identity,
      createIdentityComponent(
        entityId,
        seat,
        options.playerNames?.[String(seat)] ??
          text(world.locale, "common.player_name", { id: seat }),
      ),
    );
    world.addComponent(entityId, COMPONENT.Role, roleComp);
    world.addComponent(entityId, COMPONENT.Camp, createCampComponent(roleComp.camp, world.locale));
    const membership = roleCatalog.requireRuntime(role).initialVictoryAffiliations;
    world.addComponent(
      entityId,
      COMPONENT.Victory,
      createVictoryComponent(
        typeof membership === "function"
          ? membership(roleComp, { boardConfig: config, locale: world.locale })
          : (membership ?? [{ kind: "faction", faction: roleComp.camp }]),
      ),
    );
    world.addComponent(entityId, COMPONENT.Alive, createAliveComponent(true, world.locale));
    world.addComponent(entityId, COMPONENT.StatusMarks, createStatusMarksComponent(world.locale));
    world.addComponent(
      entityId,
      COMPONENT.VotingRight,
      createVotingRightComponent(1, true, world.locale),
    );
    world.addComponent(entityId, COMPONENT.Badge, createBadgeComponent(false, false, world.locale));
    ids.push(entityId);
  }

  if (config.roleSetups.some((row) => row.role === Role.Thief && row.count === 1))
    installThiefDeal(world, roles, ids);
  if (config.roleSetups.some((row) => row.role === Role.Shapeshifter && row.count === 1))
    installShapeshifterDeal(world, roles, ids);
  installInitialRoster(world);
  if (config.animalDream) installAnimalAuthority(world, config);
  if (roles.includes(Role.Alchemist) || roles.includes(Role.RavenClawWolf))
    installMistRavenBoard(world);
  if (config.radiantEclipse) installRadiantEclipseBoard(world);
  if (roles.includes(Role.DayScholar) || roles.includes(Role.NightMentor))
    installScholarMentorBoard(world);
  if (roles.includes(Role.TimeWolfConsort)) installTimeConsortBoard(world);
  if (roles.includes(Role.Trickster)) installTricksterBoard(world);
  if (roles.includes(Role.Magician)) installMagicianBoard(world);
  if (roles.includes(Role.WolfSorcerer)) installWolfSorcererBoard(world);
  if (roles.includes(Role.OrderPrince)) installOrderPrinceBoard(world);
  if (roles.includes(Role.EvilKnight)) installEvilKnightBoard(world);
  if (roles.includes(Role.NightmareShadow)) installNightmareBoard(world);
  if (config.nobleSecretBody)
    installNobleBodyAuthority(
      world,
      ids.find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.NightNoble)!,
      ids.find((id) => world.getComponent(id, COMPONENT.Role)?.role === Role.AwakenedIdiot)!,
    );
  if (roles.includes(Role.DemonHunter)) installDemonHunter(world, config);
  if (roles.includes(Role.GhostBride)) installGhostBride(world, config);
  installWildChild(world, config);
  installLonelyGirl(world, config);
  return { playerIds: ids, parameters };
}

function buildRoleDeck(
  config: ReadonlyBoardConfig,
  fixedRoles: readonly Role[] | undefined,
  random: RandomSource,
): Role[] {
  const deck = buildSupportedRoleDeck(config, fixedRoles, getDefaultRoleCatalog, supportsWallRoles);
  return fixedRoles ? deck : shuffled(deck, random);
}

/**
 * 定义角色组件与不透明只读私有容器的数据结构。输入为角色与阵营；输出保持原组件和
 * 空记录引用。领域不查询语言、格式化提示、初始化机制槽或冻结演员；实际展示由游戏侧
 * 创建／Catalog 装配，读方不取得私有容器写权，原 role/camp 写权限仍由具体所有者负责。
 */
import { Camp, Role } from "@ai-werewolf-arena/game-contract";

export interface RoleComponent {
  role: Role;
  camp: Camp;
  readonly privateState: object;
}

/** 仅创建领域数据；机制初始化与展示绑定在实际游戏装配处执行。 */
export function createRoleComponent(role: Role, camp: Camp): RoleComponent {
  return { role, camp, privateState: {} };
}

/**
 * 负责 mock、smoke 与规则测试的特权基线决策。输入为原 World、请求和角色目录，
 * 输出为按既定席位与角色策略选出的工具动作；可读取真实阵营，不作为玩家受限观察或生产模型回退。
 * 本模块拥有启发式选择，行动许可、付款、事实发布和最终规则结算仍由引擎及具体机制重检。
 * 无模型、网络或独立随机源；候选按原查询时点读取，异常保留已完成的读取与脚本前缀。
 */
import { roleInspectionPolicy } from "@ai-werewolf-arena/game-contract/role-inspection-policy";
import { scholarMentorBonusTargets } from "../mechanisms/roles/scholar_mentor/night_frame";
import { prohibitsLoversVote } from "../mechanisms/roles/cupid/relation";
import { text } from "@ai-werewolf-arena/game-text";
import { COMPONENT } from "../../core/domain/components/names";
import { RoleComponent } from "../../core/domain/components/role";
import {
  ActionProvider,
  ActionRequest,
  Camp,
  EntityId,
  Phase,
  Role,
  ToolCall,
} from "../../core/domain";
import { World } from "../../core/domain/world";
import { RoleCatalog, getDefaultRoleCatalog, wolfTeamPermissions, allNightAbilities, activeNightAbility, ROLE_INSPECTION_POLICY_ROLES } from "../mechanisms";
import { canBeExiled, canBeSheriff, canVote } from "../mechanisms/common/participation";

/**
 * 明确特权的基线机器人：仅供 mock、smoke 和规则测试驱动，不作为生产模型回退。
 */
export class BaselineBotActionProvider implements ActionProvider {
  private readonly roleCatalog: RoleCatalog;

  constructor(
    private readonly world: World,
    roleCatalog: RoleCatalog = getDefaultRoleCatalog(),
  ) {
    this.roleCatalog = roleCatalog;
  }

  /**
   * 根据阶段与角色生成默认动作。
   */
  async getAction(request: ActionRequest): Promise<ToolCall | null> {
    if (request.allowedTools.includes("write_note"))
      return { name: "write_note", args: { text: "..." } };
    if (request.allowedTools.includes("debate_vote"))
      return { name: "debate_vote", args: { support: true } };
    const role = this.world.getComponent(request.actorId, COMPONENT.Role);
    if (!role) {
      return null;
    }

    if (request.allowedTools.includes("choose_badge_successor")) {
      const id = request.context.badge_candidates?.find((id) =>
        canBeSheriff(this.world, id, this.roleCatalog),
      );
      return { name: "choose_badge_successor", args: { target_id: id ?? null } };
    }
    if (request.allowedTools.includes("choose_direction")) {
      if (!canBeSheriff(this.world, request.actorId, this.roleCatalog)) return null;
      // 基线策略：偶数位顺时针，奇数位逆时针，保证可重复。
      return {
        name: "choose_direction",
        args: {
          direction: request.actorId % 2 === 0 ? "clockwise" : "counter_clockwise",
        },
      };
    }

    if (request.allowedTools.includes("run_for_sheriff")) {
      if (!canBeSheriff(this.world, request.actorId, this.roleCatalog)) return null;
      // 基线策略：存活玩家默认上警，避免“需至少一次行动”的回合无动作。
      return {
        name: "run_for_sheriff",
        args: { run: true },
      };
    }

    if (request.allowedTools.includes("vote_for_sheriff")) {
      if (
        !canVote(this.world, request.actorId, this.roleCatalog) ||
        request.context.sheriff_candidates?.includes(request.actorId)
      )
        return null;
      const rawCandidates = request.context.sheriff_candidates;
      const candidates = Array.isArray(rawCandidates)
        ? rawCandidates
            .map((item) => Number(item))
            .filter(
              (id) =>
                Number.isFinite(id) && id > 0 && canBeSheriff(this.world, id, this.roleCatalog),
            )
        : [];
      const preferred = candidates.find((id) => id !== request.actorId) ?? candidates[0];
      if (preferred !== undefined) {
        return {
          name: "vote_for_sheriff",
          args: { target_id: preferred, abstain: false },
        };
      }
      return {
        name: "vote_for_sheriff",
        args: { target_id: null, abstain: true },
      };
    }

    if (request.allowedTools.includes("speak")) {
      const isLastWords = request.context.trigger === "last_words";
      return {
        name: "speak",
        args: {
          text: text(this.world.locale, isLastWords ? "fallback.last_words" : "fallback.speech", {
            actor: request.actorId,
          }),
        },
      };
    }

    if (request.phase === Phase.Voting && request.allowedTools.includes("vote")) {
      if (
        !canVote(this.world, request.actorId, this.roleCatalog) ||
        request.context.exile_candidates?.includes(request.actorId)
      )
        return null;
      // 席位顺序提供确定的默认目标；角色资格与情侣禁票仍逐目标查询，不能据此绕过网关复验。
      const target =
        this.world
          .getAliveEntityIds()
          .find(
            (id) =>
              id !== request.actorId &&
              (request.context.exile_candidates === undefined ||
                request.context.exile_candidates.includes(id)) &&
              canBeExiled(this.world, id, this.roleCatalog) &&
              !prohibitsLoversVote(this.world, request.actorId, id),
          ) ?? null;
      return target !== null
        ? { name: "vote", args: { target_id: target, abstain: false } }
        : { name: "vote", args: { target_id: null, abstain: true } };
    }

    // 绑定动作使用原能力实例；没有实例、不是夜间或本夜未激活时不退回持有者原生技能。
    const bound = request.context.ability_id
      ? allNightAbilities(role).find((ability) => ability.id === request.context.ability_id)
      : undefined;
    if (
      request.context.ability_id &&
      (!bound ||
        request.phase !== Phase.Night ||
        !activeNightAbility(role, bound.kind, request.context.day, bound.id))
    )
      return null;
    const abilityRole =
      bound?.kind === "shelter"
        ? Role.RadiantCount
        : bound?.kind === "role_check"
          ? ROLE_INSPECTION_POLICY_ROLES[roleInspectionPolicy(bound.state)]
          : bound?.kind === "seer_check"
            ? Role.Seer
            : bound?.kind === "guard"
              ? Role.Guard
              : bound?.kind === "potion"
                ? Role.Witch
                : bound?.kind === "dream"
                  ? Role.Dreamer
                  : role.role;
    if (request.allowedTools.includes("bonus_action") && request.context.modifier_bonus_kind) {
      const kind = request.context.modifier_bonus_kind,
        target =
          scholarMentorBonusTargets(this.world, request.context.day, request.actorId, kind)[0] ??
          null;
      return { name: "bonus_action", args: { kind, target_id: target, abstain: target === null } };
    }
    // 角色基线钩子可使用真实 World。这是显式特权驱动，不能复用为玩家受限观察回退。
    const roleProfile = this.roleCatalog.runtime(abilityRole);
    if (roleProfile?.baselineAction) {
      const action = roleProfile.baselineAction(
        role,
        request,
        () => this.pickAliveNotSelf(request.actorId),
        (camp) => this.pickAliveByCamp(request.actorId, this.parseCamp(camp)),
        this.world.locale,
        this.world,
      );
      if (action?.name === "speak_to_wolves" || action?.name === "kill_vote") {
        // 钩子选择之后再按当前身份、生命和夜间权限检查；选择工具并不授予狼聊或刀权。
        const access = wolfTeamPermissions(role, this.roleCatalog, this.world);
        const permitted =
          action.name === "speak_to_wolves" ? access.canChat : access.canVoteForKill;
        if (
          !permitted ||
          request.phase !== Phase.Night ||
          !this.world.getAliveEntityIds().includes(request.actorId)
        )
          return null;
      }
      return action;
    }

    return null;
  }

  /**
   * 选择任意存活且非自己的目标。
   */
  private pickAliveNotSelf(actorId: EntityId): EntityId | null {
    const target = this.world.getAliveEntityIds().find((id) => id !== actorId);
    return target ?? null;
  }

  /**
   * 按阵营选择存活目标，找不到则回退到任意非自己目标。
   */
  private pickAliveByCamp(actorId: EntityId, camp: Camp): EntityId | null {
    const target = this.world.getAliveEntityIds().find((id) => {
      const role = this.world.getComponent(id, COMPONENT.Role);
      return id !== actorId && role?.camp === camp;
    });
    // 若指定阵营无可选目标，兜底选任意存活非自己玩家。
    return target ?? this.pickAliveNotSelf(actorId);
  }

  private parseCamp(camp: "good" | "wolf" | "third_party"): Camp {
    if (camp === "wolf") {
      return Camp.Wolf;
    }
    if (camp === "third_party") {
      return Camp.ThirdParty;
    }
    return Camp.Good;
  }
}

/**
 * 管理角色资料、运行和展示的独立查询与有序注册。内建输入已经由实际组合根分开登记，
 * 自定义 flat 输入保留原对象，输出为原贡献引用与晚执行的展示绑定；查询不复制字段、提前求值 getter 或改变回调 receiver。
 * 初始化仍先于默认语言读取，展示才按当前 role 查具体贡献；Catalog 不导入捕获程序。
 * 资料、运行贡献和原文不能相互授予权限，原重复／缺失角色错误前缀保持不变。
 */
import type { Locale } from "@ai-werewolf-arena/game-contract";
import { Camp, type Role, type NativeRolePresentationId } from "@ai-werewolf-arena/game-contract";
import { roleName, text, type MessageKey } from "@ai-werewolf-arena/game-text";
import type { RoleComponent } from "../../../core/domain/components/role";
import type { World } from "../../../core/domain/world";
import { bindRolePresentation } from "../../observation/role-presentation";
import type {
  RoleContributions,
  RoleInitContext,
  RoleInitializationComponent,
  RoleMetadata,
  RoleProfile,
  RoleRuntimeContribution,
} from "./contracts";

export type NativeRoleRenderer = (
  id: NativeRolePresentationId,
  role: RoleComponent,
  locale: Locale,
  world?: World,
) => string;

/** 内建运行必须显式提供展示装配；自定义数组保持既有 flat 用户输入协议。 */
export type RoleCatalogInput =
  | readonly RoleProfile[]
  | { contributions: readonly RoleContributions[]; renderNative: NativeRoleRenderer };

type Entry =
  | { kind: "custom-profile"; profile: RoleProfile }
  | { kind: "contributions"; contributions: RoleContributions; renderNative: NativeRoleRenderer };

export class RoleCatalog {
  private readonly byRole = new Map<Role, Entry>();

  constructor(
    input: RoleCatalogInput,
    private readonly builtinMetadata: readonly RoleMetadata[],
  ) {
    // 输入形态由调用者明确选择；不为识别新协议而探测用户 profile 的新字段或 descriptor。
    if (Array.isArray(input)) {
      for (const profile of input) {
        if (this.byRole.has(profile.role))
          throw new Error(`role_profile_duplicate: ${profile.role}`);
        this.byRole.set(profile.role, { kind: "custom-profile", profile });
      }
    } else {
      const native = input as Exclude<RoleCatalogInput, readonly RoleProfile[]>;
      for (const contributions of native.contributions) {
        if (this.byRole.has(contributions.metadata.role))
          throw new Error(`role_profile_duplicate: ${contributions.metadata.role}`);
        this.byRole.set(contributions.metadata.role, {
          kind: "contributions",
          contributions,
          renderNative: native.renderNative,
        });
      }
    }
  }

  metadata(role: Role): RoleMetadata | undefined {
    const entry = this.byRole.get(role);
    return entry?.kind === "custom-profile" ? entry.profile : entry?.contributions.metadata;
  }

  runtime(role: Role): RoleRuntimeContribution | undefined {
    const entry = this.byRole.get(role);
    return entry?.kind === "custom-profile" ? entry.profile : entry?.contributions.runtime;
  }

  allMetadata(): RoleMetadata[] {
    return Array.from(this.byRole.values(), (entry) =>
      entry.kind === "custom-profile" ? entry.profile : entry.contributions.metadata,
    );
  }

  allRuntime(): { role: Role; metadata: RoleMetadata; runtime: RoleRuntimeContribution }[] {
    return Array.from(this.byRole, ([role, entry]) => ({
      role,
      metadata: entry.kind === "custom-profile" ? entry.profile : entry.contributions.metadata,
      runtime: entry.kind === "custom-profile" ? entry.profile : entry.contributions.runtime,
    }));
  }

  requireMetadata(role: Role): RoleMetadata {
    const entry = this.requireEntry(role);
    return entry.kind === "custom-profile" ? entry.profile : entry.contributions.metadata;
  }

  requireRuntime(role: Role): RoleRuntimeContribution {
    const entry = this.requireEntry(role);
    return entry.kind === "custom-profile" ? entry.profile : entry.contributions.runtime;
  }

  participation(role: RoleComponent): {
    canVote: boolean;
    canBeExiled: boolean;
    canBeSheriff: boolean;
  } {
    const runtime = this.runtime(role.role);
    if (!runtime) return { canVote: false, canBeExiled: false, canBeSheriff: false };
    return typeof runtime.participation === "function"
      ? { ...runtime.participation(role) }
      : { ...(runtime.participation ?? { canVote: true, canBeExiled: true, canBeSheriff: true }) };
  }

  getCamp(role: Role): Camp {
    return this.requireMetadata(role).camp ?? Camp.Good;
  }

  label(role: Role, locale: Locale = "zh-CN"): string {
    const metadata = this.metadata(role);
    const builtIn = this.builtinMetadata.find((entry) => entry.role === role);
    // 显式用户原文继续绕过内建翻译；仅等于原内建文字时采用原翻译策略。
    if (metadata && (!builtIn || metadata.label !== builtIn.label)) return metadata.label;
    return roleName(role, locale);
  }

  skillBrief(role: Role, locale: Locale = "zh-CN"): string {
    const metadata = this.metadata(role);
    if (!metadata) return role;
    const builtIn = this.builtinMetadata.find((entry) => entry.role === role);
    if (!builtIn || metadata.skillBrief !== builtIn.skillBrief) return metadata.skillBrief;
    return text(locale, `role.${role}.brief` as MessageKey);
  }

  applyRuntime(roleComp: RoleComponent, ctx: RoleInitContext = {}): void {
    const entry = this.requireEntry(roleComp.role);
    const runtime = entry.kind === "custom-profile" ? entry.profile : entry.contributions.runtime;
    runtime.init?.(roleComp as RoleInitializationComponent, ctx);
    const defaultLocale = ctx.locale ?? "zh-CN";
    bindRolePresentation(roleComp, (locale = defaultLocale) => {
      const active = this.requireEntry(roleComp.role);
      if (active.kind === "custom-profile") {
        // 保留原两次方法 getter、profile receiver 及随后 ctx.world 求值的完整失败前缀。
        return active.profile.renderPrompt
          ? active.profile.renderPrompt(roleComp, locale, ctx.world)
          : text(locale, "role.generic.state", {
              role: this.label(active.profile.role, locale),
            });
      }
      const presentation = active.contributions.presentation;
      if (presentation.kind === "native")
        return active.renderNative(presentation.id, roleComp, locale, ctx.world);
      return presentation.renderPrompt
        ? presentation.renderPrompt(roleComp, locale, ctx.world)
        : text(locale, "role.generic.state", {
            role: this.label(active.contributions.metadata.role, locale),
          });
    });
  }

  private requireEntry(role: Role): Entry {
    const entry = this.byRole.get(role);
    if (!entry) throw new Error(`role_profile_not_registered: ${role}`);
    return entry;
  }
}

