import type { RoleComponent } from "../../../../core/domain/components/role";
import type { RoleInitializationComponent, RoleInitContext } from "../contracts";
export function getCupidState(role: RoleComponent | undefined): CupidReadState | undefined {
  return (role as { readonly privateState: { readonly cupid?: unknown } } | undefined)?.privateState
    .cupid as CupidReadState | undefined;
}
export function projectCupidState(
  state: CupidReadState,
): import("@ai-werewolf-arena/game-contract/player-state-views").PlayerCupidState {
  const policy = playerDataField(state, "policy"),
    choice = playerDataField(state, "choice"),
    pair = playerDataField(choice, "pairIds");
  // 数组用自己的数据属性读取；共用对象读取器本来拒绝数组，不能因此执行外来编号访问器。
  const pairField = (key: string): unknown => {
    if (!Array.isArray(pair)) return undefined;
    const field = Object.getOwnPropertyDescriptor(pair, key);
    return field && Object.hasOwn(field, "value") ? field.value : undefined;
  };
  const first = pairField("0"),
    second = pairField("1");
  const positive = (id: unknown): id is number =>
    typeof id === "number" && Number.isSafeInteger(id) && id > 0;
  return {
    policy: policy === "lui_meme_lovers_only_v1" ? policy : "netease_2017_cupid_follows_lovers_v1",
    remaining: playerDataField(state, "remaining") === 1 ? 1 : 0,
    choice:
      playerDataField(choice, "day") === 1 &&
      Array.isArray(pair) &&
      pairField("length") === 2 &&
      positive(first) &&
      positive(second) &&
      first !== second
        ? { day: 1, pairIds: [first, second] }
        : null,
  };
}

/** 原完整初始化：槽不存在时才建初态，不提前读取政策或把整个私有容器复制／冻结。 */
export function installCupidState(role: RoleInitializationComponent, ctx: RoleInitContext): void {
  if (!getCupidState(role))
    role.privateState.cupid = {
      policy: ctx.boardConfig?.cupid?.policy ?? "netease_2017_cupid_follows_lovers_v1",
      remaining: 1,
      choice: null,
    };
}

/** 调用前关系已由原 owner 绑定；次数写入后的配对复制或 choice setter 失败不撤回已绑定关系或补发事实。 */
export function commitCupidChoice(state: CupidReadState, pairIds: [number, number]): void {
  (state as Pick<CupidState, "remaining">).remaining = 0;
  (state as Pick<CupidState, "choice">).choice = { day: 1, pairIds: [...pairIds] };
}

/**
 * 负责杠精选择数据槽的初始化、描述符读取、库存消耗、选择保存与玩家投影。
 * 输入为原角色／上下文或已由窗口接受的状态和选择；输出保留同一 live 槽、选择引用与独立玩家数据。
 * 初始化先求值赋值左值的容器，再读取政策；读取排除字段访问器但不新增完整 live schema 或 Proxy 零 trap 保证。
 * 窗口拥有原体、辩论提交、局部 choice 与关闭；本族命令仅写原字段，付款或保存失败不撤回此前提交。
 * 玩家投影不替代许可或档案编码，readonly 类型不冻结库存；没有镜像、JSON 身份或新的撤销政策。
 */
import type { DebaterReadState, DebaterState } from "@ai-werewolf-arena/game-contract";
import type { RoleComponent } from "../../../../core/domain/components/role";

import { playerDataField } from "../player-state-data";
import type { RoleInitializationComponent, RoleInitContext } from "../contracts";
export function getDebaterState(role: RoleComponent | undefined): DebaterReadState | undefined {
  return playerDataField(playerDataField(role, "privateState"), "debater") as
    DebaterReadState | undefined;
}
/** 提交标记只使玩家视图的 remaining 归零；不写原槽，选择仅在日期与编号为正整数时输出。 */
export function projectDebaterState(state: DebaterReadState, committed = false) {
  const choice = playerDataField(state, "choice"),
    day = playerDataField(choice, "day"),
    targetId = playerDataField(choice, "targetId");
  return {
    policy: "awa_melbourne_2026_speech_gap_v1" as const,
    remaining:
      !committed && playerDataField(state, "remaining") === 1 ? (1 as const) : (0 as const),
    choice:
      typeof day === "number" &&
      Number.isSafeInteger(day) &&
      day > 0 &&
      typeof targetId === "number" &&
      Number.isSafeInteger(targetId) &&
      targetId > 0
        ? { day, targetId }
        : null,
  };
}

/** 原初始化完整正文：仅槽不存在时安装；政策 getter 或赋值失败照原表达式传播。 */
export function initializeDebaterState(role: RoleInitializationComponent, ctx: RoleInitContext): void {
  if (!getDebaterState(role))
    role.privateState.debater = {
      policy: ctx.boardConfig?.debater?.policy ?? "awa_melbourne_2026_speech_gap_v1",
      remaining: 1,
      choice: null,
    };
}

/** 原辩论提交已记账；只消费捕获状态，不再读取角色或在后续 choice 写入失败时退款。 */
export function consumeDebaterChallenge(state: DebaterReadState): void {
  (state as Pick<DebaterState, "remaining">).remaining = 0;
}

/** 接收窗口已创建的同一 choice 引用；不复制数据、不设置窗口局部值或提交 accepted 标记。 */
export function recordDebaterChoice(state: DebaterReadState, choice: DebaterReadState["choice"]): void {
  (state as Pick<DebaterState, "choice">).choice = choice;
}

/**
 * 负责盗贼／千面人的初始选择 scope 与请求绑定。输入为原 World 参与者、首夜请求及装配端构造依赖；
 * 输出保留原选择结果与请求绑定；setup 仍当前时调用数据所有者写选择，再沿原物理换牌／身份安装顺序提交。
 * 工厂在原 scope 复验之后才 new，固定日次仍为 1；构造／请求异常保留已开准备前缀并由原 finally 关闭。
 * 失败选择与已关闭 setup 保留原终结决定；构造端口和元数据均不携带行动许可。
 * 请求记录及别名传播归独立公共实例；观察原请求或领域失配永久关该 turn；别名自身失配独立退役，期限只能缩短。
