    return undefined;
  return {
    mustChoose: scope.required,
    allowedSlots: [...scope.allowedSlots],
    cards: scope.cards.map((card, slot) => ({
      slot: slot as InitialIdentitySlot,
      role: card.role,
    })),
  };
}
export class InitialIdentitySetupWindow {
  constructor(
    private readonly world: World,
    private readonly gateway: ToolGateway,
    private readonly events: GameEvent[],
    private readonly kind: InitialIdentityKind,
    /** 保存装配端对象；原创建点才读取构造器，不提前捕获类或共享已创建的工厂。 */
    private readonly construction: { readonly requestFactory: ActionRequestFactoryConstructorPort },
  ) {}
  async execute(
    config: ReadonlyBoardConfig,
    provider: ActionProvider,
    day: number,
    isCurrent: () => boolean,
  ): Promise<boolean> {
    if (initialIdentityKind(this.world) !== this.kind) return true;
    if (hasActiveInitialIdentitySetup(this.world)) throw new Error(`${this.kind}_setup_reentry`);
    if (initialIdentitySetupReady(this.world)) return true;
    if (day !== 1 || initialIdentitySetupStatus(this.world) !== "pending" || !isCurrent())
      throw new Error(`${this.kind}_setup_unavailable`);
    const deal = openInitialIdentitySetup(this.world);
    let status: "complete" | "cancelled" | "failed" = "failed";
    let delivery: RequestLeaseTurn | undefined, failed = false;
    try {
      if (!pendingInitialIdentityDealValid(this.world)) {
        status = "cancelled";
        return false;
      }
      const actorIds = this.world
        .getAliveEntityIds()
        .filter(
          (id) =>
            this.world.getComponent(id, COMPONENT.Role)?.role === initialIdentityRole(this.kind),
        );
      if (actorIds.length === 0) {
        status = "complete";
        return true;
      }
      if (actorIds.length !== 1) throw new Error(`${this.kind}_actor_invalid`);
      const actorId = actorIds[0]!,
        actor = captureDebateParticipant(this.world, actorId),
        state = getInitialIdentityState(actor?.role, this.kind),
        camp = this.world.getComponent(actorId, COMPONENT.Camp),
        victory = this.world.getComponent(actorId, COMPONENT.Victory);
      const cards = deal.reserve.map((card) => {
        const data = readInitialIdentityCard(card);
        return data ? { card, ...data } : null;
      });
      const configJson = frozenJson(config),
        victoryJson = frozenJson(victory);
      if (
        !actor ||
        actor.camp !== Camp.Good ||
        !state ||
        !camp ||
        !victory ||
        cards.some((card) => !card) ||
        configJson === null ||
        victoryJson === null
      ) {
        status = "cancelled";
        return false;
      }
      const participants = this.world
        .entityIds()
        .map((id) => captureDebateParticipant(this.world, id));
      if (participants.some((p) => !p)) {
        status = "cancelled";
        return false;
      }
      const scope: InitialIdentityScope = {
        world: this.world,
        kind: this.kind,
        actorId,
        deal,
        reserve: deal.reserve,
        hands: deal.hands,
        cards: cards as [CardScope, CardScope],
        originalHand: deal.hands.get(actorId)!,
        participants: participants as DebateParticipant[],
        actor,
        state,
        camp,
        victory,
        victoryJson,
        config,
        configJson,
        isCurrent,
        required: initialIdentityChoiceRule(
          this.kind,
          cards.map((c) => c!.role),
        ).mustChoose,
        allowedSlots: initialIdentityChoiceRule(
          this.kind,
          cards.map((c) => c!.role),
        ).allowedSlots,
      };
      scopes.set(this.world, scope);
      if (!sameInitialIdentityScope(scope)) {
        status = "cancelled";
        return false;
      }
      // 原 scope 已安装并复验后才读取构造器；构造或 create 失败仍走下方原 finally 关闭。
      const request = new this.construction.requestFactory(this.world, this.events, 1).create({
        phase: Phase.Night,
        actorId,
        allowedTools: [initialIdentityTool(this.kind)],
        stage: this.kind,
        requiresAction: scope.required,
        summary: {
          key:
            this.kind === "shapeshifter"
              ? "turn.shapeshifter.required"
              : scope.required
                ? "turn.thief.required"
                : "turn.thief.optional",
        },
        context: { allow_fallback: false, action_failure_policy: "error" },
      });
      // 绑定表不抢 guard；真实窗口在完整 create 返回后才打开自己的交付和完成身份。
      delivery = requestLease.openDelivery(this.world, request);
      if (!sameInitialIdentityScope(scope) || delivery?.current() !== true) {
        status = "cancelled";
        return false;
      }
      const call = await provider.getAction(request);
      if (!sameInitialIdentityScope(scope) || delivery?.current() !== true) {
        status = "cancelled";
        return false;
      }
      let slot: InitialIdentitySlot | null = null;
      if (call === null) {
        if (scope.required) throw new Error(`${this.kind}_required_choice_missing`);
      } else {
        const choiceCall = readInitialIdentityTool(call, this.kind);
        if (!choiceCall) throw new Error(`${this.kind}_choice_invalid`);
        const valid = this.gateway.validateAndSanitize(this.world, actorId, choiceCall, {
          phase: Phase.Night,
          day: 1,
          ...(this.kind === "thief" ? { thiefScope: scope } : { shapeshifterScope: scope }),
        });
        if (!sameInitialIdentityScope(scope) || delivery.current() !== true) {
          status = "cancelled";
          return false;
        }
        if (!valid.ok || !scope.allowedSlots.includes(choiceCall.args.slot))
          throw new Error(`${this.kind}_choice_invalid`);
        slot = choiceCall.args.slot;
      }
      const chosen = slot === null ? null : scope.cards[slot].card;
      const catalog = getDefaultRoleCatalog();
      const newRole = chosen
        ? createRoleComponent(chosen.role, catalog.getCamp(chosen.role), this.world.locale)
        : null;
      if (newRole)
        catalog.applyRuntime(newRole, {
          boardConfig: config,
          locale: this.world.locale,
          world: this.world,
        });
      const newCamp = newRole ? createCampComponent(newRole.camp, this.world.locale) : null;
      const newVictory = newRole
        ? createVictoryComponent([{ kind: "faction", faction: newRole.camp }])
        : null;
      if (!sameInitialIdentityScope(scope) || delivery.current() !== true) {
        status = "cancelled";
        return false;
      }
      // 物理交换与身份安装之间没有 await、Provider 回调或事件发表。
      if (chosen && slot !== null && newRole && newCamp && newVictory) {
        if (this.kind === "shapeshifter") {
          consumeShapeshifterState(state, slot);
        }
        selectInitialIdentityCard(this.world, actorId, slot);
        // 一旦候选身份开始安装，该核心段失败就永久撤销候选的执行授权；不在 catch 查询 World 或退休旧演员。
        try {
          this.world.addComponent(actorId, COMPONENT.Role, newRole);
          this.world.addComponent(actorId, COMPONENT.Camp, newCamp);
          this.world.addComponent(actorId, COMPONENT.Victory, newVictory);
        } catch (error) {
          retireRoleExecution(newRole);
          throw error;
        }
      } else {
        consumeRetainedInitialIdentityState(state);
        selectInitialIdentityCard(this.world, actorId, null);
      }
      status = "complete";
      closeInitialIdentitySetup(this.world, status);
      scopes.delete(this.world);
      // 物理换牌、全部组件安装与原关闭成功后才落 true；事实／通知晚抛不能再结算 false。
      delivery.complete();
      const data = {
        actorId,
        day: 1 as const,
        role: newRole?.role ?? initialIdentityRole(this.kind),
        camp: newRole?.camp ?? Camp.Good,
      };
      this.events.push(
        this.kind === "shapeshifter"
          ? {
              timestamp: Date.now(),
              type: "shapeshifter_identity_chosen",
              payload: {
                ...data,
                slot: slot!,
                policy: "awa_netease_shapeshifter_two_extra_villagers_v1",
              },
            }
          : {
              timestamp: Date.now(),
              type: "thief_identity_chosen",
              payload: { ...data, slot, policy: "lui_meme_thief_two_extra_villagers_v1" },
            },
      );
      return true;
    } catch (error) {
      failed = true;
      throw error;
    } finally {
      try {
      if (this.kind === "shapeshifter" && status !== "complete") {
        const original =
          scopes.get(this.world)?.state ??
          this.world
            .entityIds()
            .map((id) =>
              getInitialIdentityState(this.world.getComponent(id, COMPONENT.Role), this.kind),
            )
            .find(Boolean);
        cancelShapeshifterState(original);
      }
      scopes.delete(this.world);
      closeInitialIdentitySetup(this.world, status);
      } catch (error) {
        // 原 finally 的清理错误仍按旧 JS 优先于 body 错误；新 false 通知不得覆盖它。
        failed = true;
        throw error;
      } finally {
        if (failed) { try { delivery?.close(); } catch { /* 已有原错误时只完成关闭，保该错误。 */ } }
        else delivery?.close();
      }
    }
  }
}

/**
 * 负责在校验和提交时点查询原生自爆资格。输入为当前角色及 Catalog 的运行贡献；输出为原能力与未退休条件共同允许的资格，不写状态、开启自爆窗口或授予请求权限。正常阵营变化不自动退休，恢复失败对象字段也不能恢复执行。
 */
import type { RoleComponent } from "../../../core/domain/components/role";
import type { RoleCatalog } from "./catalog";
import { isRoleExecutionRetired } from "../../../core/domain/role-execution-authority";

export function canRoleSelfDestruct(role: RoleComponent, catalog: RoleCatalog): boolean {
  const capability = catalog.runtime(role.role)?.canSelfDestruct;
  // 保原 callback 裸调用及其异常；能力读取成功之后才叠加不可恢复的演员退休拒绝。
  const allowed = typeof capability === "function" ? capability(role) : capability === true;
  if (allowed && isRoleExecutionRetired(role)) return false;
  return allowed;
}

/**
 * 负责分别推导狼队知识、聊天参与和刀权。输入为当前 World 角色及明确运行政策；输出保留队友、狼聊、狼刀名单和事件受众。狼阵营本身不等于拥有全部狼队权限，不据历史知识授予当前刀权。身份安装失败的退休仅关闭狼聊／刀执行，不抹已知队友或改写历史受众。
 */
import { scholarMentorPackBlocked } from "./scholar_mentor/night_frame";
import { animalPackKnifeBlocked } from "./animal_dream/authority";
import { nightmareKnifeBlocked } from "./nightmare_shadow/night_frame";
import { weddingMember, ghostBrideReady, weddingSetup } from "./ghost_bride/authority";
import { initialIdentitySetupReady } from "./initial_identity/deal";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import { isRoleExecutionRetired } from "../../../core/domain/role-execution-authority";
import {
  Camp,
  type EntityId,
  type GameEvent,
  type WolfTeamEventType,
} from "../../../core/domain/model";
import type { World } from "../../../core/domain/world";
import type { RoleCatalog } from "./catalog";
import type { WolfTeamPermissions } from "./contracts";

const NO_ACCESS: WolfTeamPermissions = Object.freeze({
  recognizedByPack: false,
  recognizes: "none",
  canChat: false,
  canVoteForKill: false,
});

/** 只查询角色当前的明确权限；不依赖全局目录，也不写入角色或库存。 */
export function wolfTeamPermissions(
  role: RoleComponent | undefined,
  catalog: RoleCatalog,
  world?: World,
): WolfTeamPermissions {
  if (world && !initialIdentitySetupReady(world)) return NO_ACCESS;
  if (!role || role.camp !== Camp.Wolf) return NO_ACCESS;
  if (world && weddingSetup(world) && (!ghostBrideReady(world) || weddingMember(world, role)))
    return NO_ACCESS;
  const permissions = catalog.runtime(role.role)?.wolfTeam;
  const result =
    typeof permissions === "function" ? permissions(role, world) : (permissions ?? NO_ACCESS);
  const current = world &&
    (nightmareKnifeBlocked(world) ||
      scholarMentorPackBlocked(world) ||
      animalPackKnifeBlocked(world))
    ? { ...result, canVoteForKill: false }
    : result;
  // 原拒绝单例仍保身份，避免知识查询把它当新权限对象而继续读取。
  if (current === NO_ACCESS) return current;
  // 原资格和阻断查询先行；退休只拒演员执行，recognized／recognizes 仍供原知识查询使用。
  return isRoleExecutionRetired(role)
    ? { ...current, canChat: false, canVoteForKill: false }
    : current;
}

export function knownWolfTeammates(
  world: World,
  actorId: EntityId,
  catalog: RoleCatalog,
): EntityId[] {
  const viewer = wolfTeamPermissions(world.getComponent(actorId, COMPONENT.Role), catalog, world);
  if (viewer === NO_ACCESS) return [];
  const role = world.getComponent(actorId, COMPONENT.Role);
  const snapshot = role?.camp === Camp.Wolf && catalog.runtime(role.role)?.knownTeammates;
  if (snapshot)
    return [...new Set(snapshot(role!, world))]
      .filter((id) => id !== actorId && world.getComponent(id, COMPONENT.Role)?.camp === Camp.Wolf)
      .sort((a, b) => a - b);
  if (viewer.recognizes === "none") return [];
  // 身份知识独立于尚未公告的死亡，不能按真实存活状态重写已知队友。
  return world
    .entityIds()
    .filter((id) => {
      if (id === actorId) return false;
      const target = world.getComponent(id, COMPONENT.Role);
      if (target?.camp !== Camp.Wolf) return false;
      if (viewer.recognizes === "all") return true;
      if (viewer.recognizes === "pack")
        return wolfTeamPermissions(target, catalog, world).recognizedByPack;
      return viewer.recognizes.includes(target.role);
    })
    .sort((a, b) => a - b);
}

export function wolfChatParticipants(world: World, catalog: RoleCatalog): EntityId[] {
  return world
    .getAliveEntityIds()
    .filter(
      (id) => wolfTeamPermissions(world.getComponent(id, COMPONENT.Role), catalog, world).canChat,
    )
    .sort((a, b) => a - b);
}

export function wolfKnifeHolders(world: World, catalog: RoleCatalog): EntityId[] {
  return world
    .getAliveEntityIds()
    .filter(
      (id) =>
        wolfTeamPermissions(world.getComponent(id, COMPONENT.Role), catalog, world).canVoteForKill,
    )
    .sort((a, b) => a - b);
}

/** 在事实发布时捕获一次受众；此受众包只用于引擎／Tape，不随后续阵营变化补发历史。 */
export function wolfTeamEvent<K extends WolfTeamEventType>(
  world: World,
  catalog: RoleCatalog,
  event: Omit<Extract<GameEvent, { type: K }>, "audience">,
): Extract<GameEvent, { type: K }> {
  const recipients = wolfChatParticipants(world, catalog);
  if (event.type === "wolf_kill_vote_cast") recipients.push(...wolfKnifeHolders(world, catalog));
  return {
    ...event,
    audience: Object.freeze([...new Set(recipients)].sort((a, b) => a - b)),
  } as Extract<GameEvent, { type: K }>;
}

/**
 * 负责提交普通狼／赤月和白狼王的已选自爆。输入为捕获玩家、已校验选择和当前窗口；输出为原资源、事件与死亡提案。退休仅拒演员执行，目标和已付前缀仍保原规则；不执行真实标死或阶段／胜负封盘。
 */
import { RED_MOON_ROLE } from "../roles/red_moon_apostle/ports";
import { commitDemonRedMoonBlast } from "../roles/demon_hunter/authority";
import { canRoleSelfDestruct } from "../roles/self_destruct_capability";
import {
  weddingMember,
  weddingSetup,
  ghostBrideReady,
  swallowWeddingBadges,
} from "../roles/ghost_bride/authority";
import {
  ActionWindow,
  Phase,
  Role,
  DeathCause,
  type SelfDestructSelection,
  type DeathSources,
  type GameEvent,
} from "../../../core/domain/model";
import { COMPONENT } from "../../../core/domain/components/names";
import type { RoleComponent } from "../../../core/domain/components/role";
import { isRoleExecutionRetired } from "../../../core/domain/role-execution-authority";
import type { World } from "../../../core/domain/world";
import { getWhiteWolfKingState, consumeWhiteWolfDetonation } from "../roles/white_wolf_king/ports";
import { getDefaultRoleCatalog } from "../roles/role-catalog-assembly";

/** 仅提交本自爆能力的资源、事件和事实，返回死亡提案；实际死亡写入由结算器负责。 */
export function commitSelfDestructSelection(
  world: World,
  choice: SelfDestructSelection,
  window: ActionWindow,
  phase: Phase,
  events: GameEvent[],
): { deaths: number[]; sources: DeathSources } | null {
  if (
    !Object.values(ActionWindow).includes(window) ||
    phase !== (window === ActionWindow.OnPreVote ? Phase.Voting : Phase.Day)
  )
    return null;
  const role = world.getComponent(choice.actorId, COMPONENT.Role);
  if (!role || !world.getComponent(choice.actorId, COMPONENT.Alive)?.alive) return null;
  const ownsWedding = weddingSetup(world) !== null;
  if (
    ownsWedding &&
    (!ghostBrideReady(world) ||
      role.role !== Role.Wolf ||
      weddingMember(world, role) ||
      ![ActionWindow.OnPreElection, ActionWindow.OnPreVote].includes(window))
  )
    return null;
  const deaths = [choice.actorId],
    sources: DeathSources = { [choice.actorId]: [DeathCause.SelfDestruct] };
  if (choice.kind === "ordinary") {
    const redMoon = String(role.role) === RED_MOON_ROLE;
    if (
      choice.targetId !== null ||
      (redMoon
        ? ![ActionWindow.OnPreElection, ActionWindow.OnPreVote].includes(window)
        : !canRoleSelfDestruct(role, getDefaultRoleCatalog()))
    )
      return null;
    // 原普通能力／赤月窗口资格已经读取；直接赤月旁路也须在实际权威付款前拒退休演员。
    if (isRoleExecutionRetired(role)) return null;
    const moon = redMoon ? commitDemonRedMoonBlast(world, choice.actorId) : null;
    if (redMoon && !moon) return null;
    if (ownsWedding) swallowWeddingBadges(world, events);
    events.push({
      timestamp: Date.now(),
      type: "wolf_self_destruct",
      payload: { wolfId: choice.actorId, window },
    });
    if (moon?.sealsNight)
      events.push({
        timestamp: Date.now(),
        type: "red_moon_night_sealed",
        payload: { actorId: choice.actorId, day: moon.day, night: moon.day + 1 },
      });
  } else if (choice.kind === "white_wolf_king") {
    const state = getWhiteWolfKingState(role);
    if (role.role !== Role.WhiteWolfKing || state?.canDetonate !== true) return null;
    if (choice.targetId !== null) {
      if (
        choice.targetId === choice.actorId ||
        !world.getComponent(choice.targetId, COMPONENT.Alive)?.alive
      )
        return null;
      deaths.push(choice.targetId);
      sources[choice.targetId] = [DeathCause.WhiteWolfBlast];
    }
    // 同一库存和原目标预检在先；退休不消费库存，不取消目标身体或回滚任何已付前缀。
    if (isRoleExecutionRetired(role)) return null;
    consumeWhiteWolfDetonation(state);
    events.push({
      timestamp: Date.now(),
      type: "white_wolf_king_self_destruct",
      payload: { actorId: choice.actorId, targetId: choice.targetId, window },
    });
  } else return null;
  return { deaths, sources };
}

