/** 只供捕获 owner 使用的原位读取端口；回调不进入观察 DTO 或玩家策略。 */
export interface PlayerObservationQueries {
  world(): World;
  role(actorId: () => EntityId): RoleComponent | undefined;
  wolfTeammates(actorId: () => EntityId): EntityId[];
  catalog(): RoleCatalog;
}

/**
 * F01：只捕获当前 actor 自己的狼队资格，不从历史队友或请求的旧工具名单推断。
 * 原政策可运行自定义 callback，因此先读结果，再核对自己的角色编号、阵营和存活量；
 * 这只是观察快照，不是原生命／请求租约；实际提交仍由原机制验证，不返回拒绝原因。
 */
function captureCurrentWolfActions(
  request: ActionRequest,
  queries: PlayerObservationQueries,
): PlayerObservation["currentWolfActions"] {
  const world = queries.world(),
    actorId = request.actorId,
    role = world.getComponent(actorId, COMPONENT.Role),
    roleId = role?.role,
    permissions = wolfTeamPermissions(role, queries.catalog(), world),
    canChat = permissions.canChat === true,
    canVoteForKill = permissions.canVoteForKill === true;
  const current =
    world.getComponent(actorId, COMPONENT.Role) === role &&
    role?.role === roleId &&
    role?.camp === Camp.Wolf &&
    world.getComponent(actorId, COMPONENT.Alive)?.alive === true;
  return current ? { canChat, canVoteForKill } : { canChat: false, canVoteForKill: false };
}

export function capturePlayerObservation(
  request: ActionRequest,
  queries: PlayerObservationQueries,
): PlayerObservation {
  const role = queries.role(() => request.actorId);
  const dead = new Set<number>();
  for (const event of request.context.visible_events) {
    if (
      (event.type === "night_resolved" || event.type === "additional_deaths") &&
      Array.isArray(event.payload.deaths)
    ) {
      for (const id of event.payload.deaths) if (typeof id === "number") dead.add(id);
    }
    const target =
      event.type === "voted_out"
        ? event.payload.target
        : event.type === "wolf_self_destruct"
          ? event.payload.wolfId
          : event.type === "player_shot" ||
              event.type === "hunter_shot" ||
              event.type === "wolf_king_shot" ||
              event.type === "mechanical_shot"
            ? event.payload.targetId
            : undefined;
    if (typeof target === "number") dead.add(target);
    if (event.type === "white_wolf_king_self_destruct") {
      if (typeof event.payload.actorId === "number") dead.add(event.payload.actorId);
      if (typeof event.payload.targetId === "number") dead.add(event.payload.targetId);
    }
    if (event.type === "knight_duel") {
      const victim =
        event.payload.result === "wolf"
          ? event.payload.targetId
          : event.payload.result === "not_wolf"
            ? event.payload.actorId
            : undefined;
      if (typeof victim === "number") dead.add(victim);
    }
  }
  const ownState: PlayerObservation["ownState"] = {};
  if (role?.role === Role.FragrantPhantom && isFragrantPairBoard(queries.world())) {
    const known = fragrantPlayerKnowledge(queries.world(), request.phase, request.context.day);
    if (known.actorId === request.actorId) ownState.fragrantPhantom = known;
  }
  if (isNobleBodyBoard(queries.world())) {
    const known = getNobleBodyPlayerState(queries.world(), request.actorId, request.phase);
    if (known?.kind === "night_noble") ownState.nightNoble = known.state;
    if (known?.kind === "secret_body") ownState.secretBody = known.state;
  }
  const alchemist = projectAlchemist(role),
    raven = projectRaven(role);
  if (alchemist) ownState.alchemist = alchemist;
  if (raven) ownState.ravenClaw = raven;
  const modifier = readModifierState(scholarMentorStateForRole(role));
  if (modifier) ownState.scholarMentor = modifier;
  const timeConsort = projectTimeConsortState(role, request.context.day);
  if (timeConsort) ownState.timeConsort = timeConsort;
  const wolfSorcerer = projectWolfSorcererState(role);
  if (wolfSorcerer) ownState.wolfSorcerer = wolfSorcerer;
  const trickster = projectTricksterState(role);
  if (trickster) ownState.trickster = trickster;
  const prince = projectOrderPrinceState(role);
  if (prince) ownState.orderPrince = prince;
  const magician = projectMagicianState(role);
  if (magician) ownState.magician = magician;
  // 各机制拥有字段裁剪；此处只按原顺序组装，末尾统一脱离并冻结整个观察。
  const redMoon = projectRedMoonState(role);
  if (redMoon) ownState.redMoon = redMoon;
  const nightmare = projectNightmareShadowState(role);
  if (nightmare) ownState.nightmare = nightmare;
  const evilKnight = projectEvilKnightState(role);
  if (evilKnight) ownState.evilKnight = evilKnight;
  const thief = projectThiefState(role, queries.world()),
    choices = projectThiefChoices(queries.world(), request.actorId);
  if (thief) ownState.thief = { ...thief, ...(choices ?? {}) };
  const shape = projectShapeshifterState(role, queries.world()),
    shapeChoices = projectShapeshifterChoices(queries.world(), request.actorId);
  if (shape) ownState.shapeshifter = { ...shape, ...(shapeChoices ?? {}) };
  const wallNote = projectWallNote(queries.world(), request.actorId);
  if (wallNote) ownState.wallNote = wallNote;
  if (debateVoteBlocked(queries.world(), request.actorId, request.context.day))
    ownState.debatePenalty = { day: request.context.day };
  if (role?.role === Role.Debater) {
    const state = getDebaterState(role);
    if (state)
      ownState.debater = projectDebaterState(
        state,
        hasDebateCommit(queries.world(), request.actorId),
      );
  }
  const lover = projectLover(queries.world(), request.actorId);
  if (lover) ownState.lover = lover;
  if (role?.role === Role.Cupid) {
    const state = getCupidState(role);
    if (state) ownState.cupid = projectCupidState(state);
  }
  if (role?.role === Role.BlackMarketMerchant) {
    const state = getBlackMarketState(role);
    if (state) ownState.blackMarket = projectBlackMarketState(state);
  }
  const wedding = weddingActorView(queries.world(), request.actorId);
  if (wedding) ownState.wedding = wedding;
  if (role?.role === Role.GhostBride) {
    const brideState = weddingBrideState(queries.world(), request.actorId);
    if (brideState) ownState.ghostBride = brideState;
  }
  if (role?.role === Role.DemonHunter)
    ownState.demonHunter = projectDemonHunter(queries.world(), role);
  if (role?.role === Role.LonelyGirl)
    ownState.lonelyGirl = projectLonelyGirl(queries.world(), role);
  if (role?.role === Role.WildChild) ownState.wildChild = projectWildChild(queries.world(), role);
  if (role?.role === Role.Hybrid) {
    const state = getHybridState(role);
    if (state) ownState.hybrid = projectHybridState(state);
  }
  if (role?.role === Role.MiracleMerchant) {
    const state = getMerchantState(role);
    if (state) ownState.merchant = projectMerchantState(state);
  }
  if (role?.role === Role.EclipseMaid) ownState.eclipse = projectEclipseState(role);
  const witch = role ? getWitchState(role, request.context.ability_id) : undefined;
  const guard = role ? getGuardState(role, request.context.ability_id) : undefined;
  if (witch) ownState.witch = projectWitchState(witch);
  if (guard) ownState.guard = projectGuardState(guard);
  if (role?.role === Role.Hunter) {
    const state = getHunterState(role);
    if (state) ownState.hunter = projectHunterState(state);
  }
  if (role?.role === Role.WolfBeauty) {
    if (isAnimalDreamBoard(queries.world()))
      ownState.wolfBeauty = animalBeautyKnowledge(queries.world(), request.actorId);
    else {
      const state = getWolfBeautyState(role);
      if (state) ownState.wolfBeauty = projectWolfBeautyState(state);
    }
  }
  if (role?.role === Role.Bear) {
    if (isAnimalDreamBoard(queries.world())) ownState.bear = animalBearKnowledge(queries.world());
    else {
      const state = getBearState(role);
      if (state) ownState.bear = projectBearState(state);
    }
  }
  if (role?.role === Role.FoxCub)
    ownState.foxCub = animalFoxKnowledge(queries.world(), request.actorId);
  if (role?.role === Role.WhiteCat)
    ownState.whiteCat = animalCatKnowledge(queries.world(), request.actorId);
  if (role?.role === Role.Pufferfish)
    ownState.pufferfish = animalPufferKnowledge(queries.world(), request.actorId);
  if (role?.role === Role.HiddenWolf) {
    const state = getHiddenWolfState(role);
    ownState.hiddenWolf = {
      hasInheritedKnife: state?.hasInheritedKnife === true,
      canVoteForKill: canHiddenWolfKnife(role, queries.world()),
      ...(state?.campInspection === "netease_2020_good_v1"
        ? { campInspection: state.campInspection }
        : {}),
    };
  }
  if (role?.role === Role.Gargoyle)
    ownState.gargoyle = {
      hasInheritedKnife: getGargoyleState(role)?.hasInheritedKnife === true,
      canVoteForKill: canGargoyleKnife(role, queries.world()),
    };
  if (role?.role === Role.MechanicalWolf) {
    const state = getMechanicalState(role);
    if (state) ownState.mechanical = projectMechanicalState(state);
  }
  if (role?.role === Role.AwakenedHiddenWolf) {
    const state = getAwakenedState(role);
    if (state) ownState.awakened = projectAwakenedState(state);
  }
  if (role) {
    const inspection = getRoleInspectionState(role, request.context.ability_id);
    if (inspection) ownState.roleInspection = projectRoleInspectionState(inspection);
  }
  if (role?.role === Role.WolfKing) {
    const state = getWolfKingState(role);
    if (state) ownState.wolfKing = projectWolfKingState(state);
  }
  if (role?.role === Role.WhiteWolfKing) {
    const state = getWhiteWolfKingState(role);
    if (state) ownState.whiteWolfKing = projectWhiteWolfKingState(state);
  }
  if (role?.role === Role.Knight) {
    const state = getKnightState(role);
    if (state) ownState.knight = projectKnightState(state);
  }
  if (role?.role === Role.Gravekeeper) {
    ownState.gravekeeper = projectGravekeeperState(role);
  }
  if (role?.role === Role.Idiot) {
    const state = getIdiotState(role);
    if (state) ownState.idiot = projectIdiotState(state);
  }
  const seer = role ? getSeerState(role, request.context.ability_id) : undefined;
  if (seer) ownState.seer = projectSeerState(seer);
  const dreamer = role ? getDreamerState(role, request.context.ability_id) : undefined;
  if (dreamer) ownState.dreamer = projectDreamerState(dreamer);
  const {
    wall_id: _wallId,
    death_action_id: _deathActionId,
    debate_id: _debateId,
    ...context
  } = request.context;
  return freezeObservation({
    request: { ...request, context },
    identity: {
      ...(role ? { role: role.role, camp: role.camp } : {}),
      name: queries.world().getComponent(request.actorId, COMPONENT.Identity)?.name,
    },
    knownAliveIds: queries
      .world()
      .entityIds()
      .filter((id) => !dead.has(id)),
    teammateIds: queries.wolfTeammates(() => request.actorId),
    ownState,
    ownNightActions: ownNightActions(queries.world(), request.actorId, request.context.day),
    abilities: allNightAbilities(role).map((ability) =>
      projectNightAbility(ability, request.context.day),
    ),
    deathAbilities: allDeathGuns(role).map(projectDeathGun),
    // 原知识、能力和发布存活字段已在原位置读完；新的自身资格单独捕获，不改写它们。
    currentWolfActions: captureCurrentWolfActions(request, queries),
  });
}

/**
 * 负责角色展示的实际创建与运行绑定。输入是原角色、阵营、默认语言或 Catalog 安装的
 * 展示闭包；输出保持同一角色对象、当前 role 标签和晚调用的提示。绑定仅保存旧闭包的
 * 展示元数据，不复制 privateState、World 或库存，不授予行动或编码归档。
 * 未 applyRuntime 的角色只展示 component.role；只有实际初始化后才消费内建／自定义贡献。
 */
import type { Locale } from "@ai-werewolf-arena/game-contract";
import { roleName, text } from "@ai-werewolf-arena/game-text";
import { Camp, Role } from "@ai-werewolf-arena/game-contract";
import {
  createRoleComponent as createDomainRoleComponent,
  type RoleComponent,
} from "../../core/domain/components/role";

// 唯一展示绑定保存原闭包引用；角色状态仍只在 World 中的原组件。
const presentations = new WeakMap<RoleComponent, (locale?: Locale) => string>();

export function createRoleComponent(
  role: Role,
  camp: Camp,
  locale: Locale = "zh-CN",
): RoleComponent {
  const component = createDomainRoleComponent(role, camp);
  bindRolePresentation(component, (displayLocale: Locale = locale) =>
    text(displayLocale, "component.role", { role: roleName(component.role, displayLocale) }),
  );
  return component;
}

/** 初始化所有者安装闭包；调用方不能据此获得角色私有状态写权限。 */
export function bindRolePresentation(
  role: RoleComponent,
  renderer: (locale?: Locale) => string,
): void {
  presentations.set(role, renderer);
}

/** 保留原可选 render 方法的存在性语义，调用时才执行已绑定的具体贡献。 */
export function rolePresentationRenderer(
  role: RoleComponent | undefined,
): ((locale?: Locale) => string) | undefined {
  return role && presentations.get(role);
}

export function renderRolePrompt(role: RoleComponent, locale?: Locale): string {
  const renderer = rolePresentationRenderer(role);
  if (!renderer) throw new Error("role_presentation_not_bound");
  return renderer(locale);
}

/**
 * 负责白天自爆的有限规则组合：婚礼禁用、红月资格、普通自爆与白狼王库存共同约束选择。
 * 输入为原 World、角色工具表、请求构造端口、Provider、网关及窗口回调；输出为首个未被拒绝的选择或 null。
 * 并发请求保原 Promise.all 顺序；等待后按原体／生命版本／库存与目标复验，再按玩家编号尝试提交。
 * 捕获的存活组件和资源引用仅服务本次窗口；阶段 current、库存付款、死亡与最终判胜各归原 owner。安装失败的退休只拒演员，目标和纯数据仍保原查询。
 * commit 返回 false 只跳过该选择；读取、Provider 或提交失败沿原异常传播，不补提交或回滚已写前缀。
 */
import type { ReadonlyBoardConfig } from "@ai-werewolf-arena/game-contract";
import { RED_MOON_ROLE } from "../game/mechanisms/roles/red_moon_apostle/ports";
import { demonRedMoonCanBlast } from "../game/mechanisms/roles/demon_hunter/ports";
import { canRoleSelfDestruct } from "../game/mechanisms/roles/self_destruct_capability";
import { getDefaultRoleCatalog } from "../game/mechanisms/roles/role-catalog-assembly";
import {
  weddingMember,
  weddingSetup,
  ghostBrideReady,
} from "../game/mechanisms/roles/ghost_bride/ports";
import { AliveComponent, aliveLifeVersion } from "../core/domain/components/alive";
import { COMPONENT } from "../core/domain/components/names";
import { RoleComponent } from "../core/domain/components/role";
import { isRoleExecutionRetired } from "../core/domain/role-execution-authority";
import {
  ActionProvider,
  ActionWindow,
  Phase,
  type SelfDestructSelection,
} from "../core/domain/model";
import { RoleRegistry } from "../core/domain/registries/role_registry";
import { World } from "../core/domain/world";
import { ToolGateway } from "../game/gateway/tool_gateway";
import type { ActionRequestConstructionPort } from "../core/domain/actions";
import { getWhiteWolfKingState } from "../game/mechanisms/roles/white_wolf_king/ports";

/** 并发收集选项，按编号升序复验并尝试提交；回调明确返回 false 时跳过该选项，返回首个未被拒绝的选择。 */
export class SelfDestructWindow {
  constructor(
    private readonly world: World,
    private readonly roleRegistry: RoleRegistry,
    private readonly toolGateway: ToolGateway,
  ) {}

  async execute(
    requests: ActionRequestConstructionPort,
    provider: ActionProvider,
    window: ActionWindow,
    phase: Phase,
    isCurrent: () => boolean = () => true,
    commit?: (choice: SelfDestructSelection) => Promise<void | boolean>,
  ): Promise<SelfDestructSelection | null> {
    if (!isCurrent()) return null;
    // 先捕获所有原存活身体和生命版本；后续目标死后复活或换组件不能复用旧选择。
    const targets = new Map(
      this.world.getAliveEntityIds().map((id) => {
        const alive = this.world.getComponent(id, COMPONENT.Alive)!;
        return [id, { alive, version: aliveLifeVersion(alive) }] as const;
      }),
    );
    // 各玩家请求并发，结果排列仍由原存活名单决定；不以最早响应决定谁自爆。
    const picks = await Promise.all(
      this.world.getAliveEntityIds().map(async (actorId) => {
        const role = this.world.getComponent(actorId, COMPONENT.Role);
        if (!role) return null;
        if (
          weddingSetup(this.world) &&
          (!ghostBrideReady(this.world) || weddingMember(this.world, role))
        )
          return null;
        const tools = this.roleRegistry.getAllowedTools(role.role);
        const tool = tools.includes("self_destruct_with_target")
          ? "self_destruct_with_target"
          : tools.includes("self_destruct")
            ? "self_destruct"
            : null;
        if (!tool) return null;
        if (
          tool === "self_destruct" &&
          (String(role.role) === RED_MOON_ROLE
            ? !demonRedMoonCanBlast(this.world, actorId)
            : !canRoleSelfDestruct(role, getDefaultRoleCatalog()))
        )
          return null;
        // 白狼王复验同一库存对象；这里不消费，实际消耗仍归提交函数。
        const resource =
          tool === "self_destruct_with_target" ? getWhiteWolfKingState(role) : undefined;
        if (tool === "self_destruct_with_target" && resource?.canDetonate !== true) return null;
        // 原特殊资格和库存读取先行，保其首错误；已退休演员不再建立新请求。
        if (isRoleExecutionRetired(role)) return null;
        const life = targets.get(actorId)!;
        const request = requests.create({
          phase,
          actionWindow: window,
          actorId,
          allowedTools: [tool],
          stage: window,
          requiresAction: false,
          summary: {
            key:
              phase === Phase.Voting
                ? "request.summary.self_destruct_pre_vote"
                : "request.summary.self_destruct",
          },
          context: {},
        });
        const action = await provider.getAction(request);
        if (
          action?.name !== tool ||
          (action.name !== "self_destruct" && action.name !== "self_destruct_with_target")
        )
          return null;
        const choice: SelfDestructSelection =
          action.name === "self_destruct"
            ? { kind: "ordinary", actorId, targetId: null }
            : { kind: "white_wolf_king", actorId, targetId: action.args.target_id };
        return { choice, action, role, resource, life };
      }),
    );
    if (!isCurrent()) return null;
    // 提交前重复检查原玩家、目标、生命版本及特殊规则；字段恢复不抹去生命版本变化。
    const stillCurrent = (pick: NonNullable<(typeof picks)[number]>) => {
      const { actorId, targetId } = pick.choice;
      if (
        !isCurrent() ||
        (weddingSetup(this.world) &&
          (!ghostBrideReady(this.world) || weddingMember(this.world, pick.role))) ||
        this.world.getComponent(actorId, COMPONENT.Role) !== pick.role ||
        this.world.getComponent(actorId, COMPONENT.Alive) !== pick.life.alive ||
        !pick.life.alive.alive ||
        pick.life.version === undefined ||
        aliveLifeVersion(pick.life.alive) !== pick.life.version
      )
        return false;
      if (String(pick.role.role) === RED_MOON_ROLE && !demonRedMoonCanBlast(this.world, actorId))
        return false;
      if (
        pick.choice.kind === "white_wolf_king" &&
        (getWhiteWolfKingState(pick.role) !== pick.resource || pick.resource?.canDetonate !== true)
      )
        return false;
      if (targetId !== null) {
        const target = targets.get(targetId);
        if (
          !target ||
          this.world.getComponent(targetId, COMPONENT.Alive) !== target.alive ||
          !target.alive.alive ||
          target.version === undefined ||
          aliveLifeVersion(target.alive) !== target.version
        )
          return false;
      }
      // 等待后先完成原特殊权威、库存与目标复验；字段恢复不复活这个失败演员。
      return !isRoleExecutionRetired(pick.role);
    };
    // 网关预检前后均复验；预检成功只产生候选，不意味着库存付款或死亡已生效。
    const valid = picks.filter(
      (pick): pick is NonNullable<typeof pick> =>
        pick !== null &&
        stillCurrent(pick) &&
        this.toolGateway.validateAndSanitize(this.world, pick.choice.actorId, pick.action, {
          phase,
          actionWindow: window,
          allowSelfDestruct: true,
        }).ok &&
        stillCurrent(pick),
    );
    // 按玩家编号串行调用可选提交；false 跳过，异常停止并保留此前提交的前缀。
    for (const pick of valid.sort((a, b) => a.choice.actorId - b.choice.actorId)) {
      if (!isCurrent()) return null;
      if (!stillCurrent(pick)) continue;
      if ((await commit?.(pick.choice)) === false) continue;
      return pick.choice;
    }
    return null;
  }
}

/** 显式空窗口列表禁用全部机会；只有未配置列表才回退到原投票前默认窗口。 */
export function isSelfDestructWindowEnabled(
  config: ReadonlyBoardConfig,
  window: ActionWindow,
): boolean {
  return config.selfDestruct?.enabledWindows === undefined
    ? window === ActionWindow.OnPreVote
    : config.selfDestruct.enabledWindows.includes(window);
}

/**
 * 负责普通狼狼聊、狼刀和自爆的完整工具准入组合，供共享普通狼装配及派生角色引用。
 * 输入为当前角色运行政策、原 World、阶段／窗口和工具上下文；输出为原首个拒绝或 null。
 * 婚礼狼刀先由鬼魂新娘原权威复验，否则依次检查狼队刀权、阶段、工具、pass 与只读目标贡献。
 * 同一可写规则表保留 callback 引用；派生展开与晚读取仍发生在原 profile／Registry 调用点。
 * 准入不执行工具、付款、开启窗口或授予租约；候选允许结果不能代替真正提交时的权限复验。
 */
import { canRoleSelfDestruct } from "../game/mechanisms/roles/self_destruct_capability";
import { bindWolfKnifeTargetQuery } from "../game/mechanisms/roles/wolf/ports";
import {
  weddingMember,
  weddingSetup,
  ghostBrideReady,
  canSubmitWeddingTool,
} from "../game/mechanisms/roles/ghost_bride/ports";
import { RuleError } from "@ai-werewolf-arena/game-contract";
import { ActionWindow, Phase } from "../core/domain/model";
import type { ToolRuleMap } from "../game/mechanisms/validation/contracts";
import { wolfTeamPermissions } from "../game/mechanisms/roles/wolf_team";

/** 三工具保持各自完整首失败顺序；不把婚礼刀权、普通候选或自爆窗口统一成新授权策略。 */
export const WOLF_VALIDATION_RULES: ToolRuleMap = {
  speak_to_wolves: ({ world, role, roleCatalog, phase }) => {
    if (!wolfTeamPermissions(role, roleCatalog, world).canChat) {
      return { code: RuleError.WolfChatPermission };
    }
    if (phase !== Phase.Night) return { code: RuleError.WolfChatPhase };
    return null;
  },
  kill_vote: ({ world, actorId, day, ghostBrideScope, role, roleCatalog, toolCall, phase }) => {
    // 婚礼分支优先；缺省日次仍为 0，不继续读取普通狼队政策或候选。
    if (weddingSetup(world))
      return canSubmitWeddingTool(world, actorId, phase, day ?? 0, ghostBrideScope, toolCall)
        ? null
        : { code: RuleError.GhostBrideUnavailable };
    if (!wolfTeamPermissions(role, roleCatalog, world).canVoteForKill) {
      return { code: RuleError.WolfKillPermission };
    }
    if (phase !== Phase.Night) return { code: RuleError.WolfKillPhase };
    if (toolCall.name !== "kill_vote") {
      return { code: RuleError.ToolMismatch };
    }
    // 原 pass 先于目标查询；非 pass 且首个目标非 null 时，保留三次 args 与两次 target_id 的现场读取。
    if (toolCall.args.abstain) {
      return null;
    }
    if (
      toolCall.args.target_id === null ||
      !bindWolfKnifeTargetQuery(world).allows(toolCall.args.target_id)
    ) {
      return { code: RuleError.KillTarget };
    }
    return null;
  },
  self_destruct: ({
    world,
    role,
    roleCatalog,
    phase,
    actionWindow,
    allowSelfDestruct,
    toolCall,
  }) => {
    // 原婚礼成员排除先于角色自爆能力；阶段与窗口关系通过后检查已取出的 allowSelfDestruct，再读工具名／confirm。
    if (weddingSetup(world) && (!ghostBrideReady(world) || weddingMember(world, role)))
      return { code: RuleError.WolfBlastOnly };
    if (!canRoleSelfDestruct(role, roleCatalog)) {
      return { code: RuleError.WolfBlastOnly };
    }
    if (phase !== Phase.Day && phase !== Phase.Voting) {
      return { code: RuleError.BlastPhase };
    }
    if (actionWindow === undefined || !Object.values(ActionWindow).includes(actionWindow)) {
      return { code: RuleError.BlastWindow };
    }
    if (phase !== (actionWindow === ActionWindow.OnPreVote ? Phase.Voting : Phase.Day))
      return { code: RuleError.BlastPhase };
    if (!allowSelfDestruct) {
      return { code: RuleError.BlastDisabled };
    }
    if (toolCall.name !== "self_destruct" || toolCall.args.confirm !== true) {
      return { code: RuleError.BlastConfirm };
    }
    return null;
  },
};

